package main

import "fmt"

// TaxBracket represents a single tax bracket with its upper limit and tax rate.
type TaxBracket struct {
	Limit float64
	Rate  float64
}

// CalculateTax calculates the income tax based on a progressive tax system.
// It takes the total income as input and returns the calculated tax amount.
func CalculateTax(income float64) (float64, error) {
	if income < 0 {
		return 0, fmt.Errorf("income cannot be negative")
	}

	// Define tax brackets (example values, can be modified)
	// Bracket 1: 0% for income up to 10,000
	// Bracket 2: 10% for income from 10,001 to 50,000
	// Bracket 3: 20% for income from 50,001 to 100,000
	// Bracket 4: 30% for income above 100,000
	brackets := []TaxBracket{
		{Limit: 10000, Rate: 0.00},  // 0% for first 10,000
		{Limit: 50000, Rate: 0.10},  // 10% for next 40,000
		{Limit: 100000, Rate: 0.20}, // 20% for next 50,000
		{Limit: -1, Rate: 0.30},     // 30% for anything above 100,000 (-1 indicates no upper limit)
	}

	var totalTax float64
	var previousBracketLimit float64

	for _, bracket := range brackets {
		if income <= previousBracketLimit {
			break
		}

		taxableInThisBracket := 0.0
		currentBracketLimit := bracket.Limit

		if currentBracketLimit == -1 || income < currentBracketLimit {
			taxableInThisBracket = income - previousBracketLimit
		} else {
			taxableInThisBracket = currentBracketLimit - previousBracketLimit
		}

		if taxableInThisBracket > 0 {
			totalTax += taxableInThisBracket * bracket.Rate
		}
		previousBracketLimit = currentBracketLimit
	}

	return totalTax, nil
}

package main

import (
	"math"
	"testing"
)

func TestCalculateTax(t *testing.T) {
	tests := []struct {
		name    string
		income  float64
		expectedTax float64
		expectError bool
	}{
		{
			name:        "Zero income",
			income:      0.0,
			expectedTax: 0.0,
			expectError: false,
		},
		{
			name:        "Income within first bracket (0%)",
			income:      5000.0,
			expectedTax: 0.0,
			expectError: false,
		},
		{
			name:        "Income exactly at first bracket limit (0%)",
			income:      10000.0,
			expectedTax: 0.0,
			expectError: false,
		},
		{
			name:        "Income in second bracket (10%)",			
			income:      20000.0, // 10000 * 0% + (20000-10000) * 10% = 1000
			expectedTax: 1000.0,
			expectError: false,
		},
		{
			name:        "Income at second bracket limit (10%)",
			income:      50000.0, // 10000 * 0% + (50000-10000) * 10% = 4000
			expectedTax: 4000.0,
			expectError: false,
		},
		{
			name:        "Income in third bracket (20%)",
			income:      75000.0, // 10000*0% + 40000*10% + (75000-50000)*20% = 0 + 4000 + 5000 = 9000
			expectedTax: 9000.0,
			expectError: false,
		},
		{
			name:        "Income at third bracket limit (20%)",
			income:      100000.0, // 10000*0% + 40000*10% + 50000*20% = 0 + 4000 + 10000 = 14000
			expectedTax: 14000.0,
			expectError: false,
		},
		{
			name:        "Income in fourth bracket (30%)",
			income:      150000.0, // 14000 + (150000-100000)*30% = 14000 + 15000 = 29000
			expectedTax: 29000.0,
			expectError: false,
		},
		{
			name:        "Negative income",
			income:      -100.0,
			expectedTax: 0.0,
			expectError: true,
		},
	}

	for _, tt := range tests {
		t := tt // Capture range variable
		t.Run(t.name, func(t *testing.T) {
			tax, err := CalculateTax(t.income)

			if t.expectError {
				if err == nil {
					t.Errorf("Expected an error for negative income, but got none")
				}
			} else {
				if err != nil {
					t.Errorf("Did not expect an error, but got: %v", err)
				}
				if math.Abs(tax-t.expectedTax) > 0.001 {
					t.Errorf("For income %.2f, expected tax %.2f, but got %.2f", t.income, t.expectedTax, tax)
				}
			}
		})
	}
}

